# application.yml: đủ thread cho các job định kỳ
spring:
  task:
    scheduling:
      pool:
        size: 4

// Job nặng: scheduler chỉ khởi động, việc nặng chạy trên executor riêng
@Component
class ReconciliationReport {
    @Scheduled(cron = "0 0 2 * * *", zone = "Asia/Ho_Chi_Minh")
    @SchedulerLock(name = "reconciliation-export", lockAtLeastFor = "5m", lockAtMostFor = "30m")   // ShedLock: chỉ một pod chạy
    void export() {
        reportExecutor.execute(reportService::exportYesterday);
    }
}

// Token: làm mới theo hạn còn lại, và thử lại một lần khi gặp 401
String token() {
    if (tokenHolder.expiresWithin(Duration.ofSeconds(10))) refreshNow();
    return tokenHolder.value();
}

<T> T callPartner(Function<String, T> call) {
    try {
        return call.apply(token());
    } catch (HttpClientErrorException.Unauthorized e) {
        refreshNow();
        return call.apply(token());
    }
}
